from pathlib import Path
import re,base64,html,json
root=Path(__file__).resolve().parent;p=root/'what-is-jev.html';s=p.read_text()
s=s.replace('“Autoregression<br>has been around<br>for decades!”','“Classifiers<br>have been around<br>forever!”')
s=s.replace('The skeptical interlude. Autoregression is longstanding; classification is also longstanding. These are distinct concepts. JEV’s novelty claim concerns its decision-focused model and interface, not inventing classification or autoregression.','The skeptical interlude: classification is longstanding. The point is reducing the setup cost of putting a classifier into an application, not inventing classification.')
s=s.replace('A general-purpose classifier for focused decisions.<br>Give it context and a question. Get a choice, a score, or a probability.','A general-purpose classifier from TypeSafe AI.<br>Fast, low-cost decisions for your application.')
s=s.replace('https://docs.typesafe.ai/concepts/confidence','https://docs.typesafe.ai/confidence')
def slide(title,body,notes):return f'<section class="slide" hidden><h2>{title}</h2>{body}<div class="notes">{html.escape(notes)}</div></section>'
def points(items):return '<div class="points">'+''.join(f'<div><h3>{a}</h3><p>{b}</p></div>' for a,b in items)+'</div>'
image=base64.b64encode((root/'lowered-bar.png').read_bytes()).decode()
bar=slide('Lowering the bar to use a classifier',f'<img class="barart" src="data:image/png;base64,{image}" alt="A person faces a high jump bar set above their head; alongside, the same person steps easily over a lowered bar."><div class="barlabels"><div><strong>Train your own</strong><span>Collect labels · prepare data · fit a model</span></div><div><strong>Start with JEV</strong><span>Describe the decision · provide context · call the API</span></div></div><p class="caveat">Less setup to get started. Evaluation still matters.</p>','The high-jump metaphor refers to the barrier to entry, not lowering the standard of correctness. The comparison is with training a task-specific classifier. Other pretrained zero-shot classifiers and LLMs also reduce training-data requirements. TypeSafe confirms shared weights and request-based customization: https://docs.typesafe.ai/models . Illustration generated for this presentation.')
sections=list(re.finditer(r'<section\b.*?</section>',s,re.S));pos=sections[2].end();s=s[:pos]+bar+s[pos:]
speed=slide('Fast, low-cost decisions in the loop','<p class="intro">An alternative to LLM calls for classification, scoring, and routing.</p><div class="metrics"><div><strong>371 ms</strong><span>Median request latency<br>in our Titanic experiment</span></div><div><strong>≈ $0.0021</strong><span>Estimated API cost<br>for all 100 predictions</span></div></div><p class="bodycopy">Use JEV for bounded decisions.<br>Keep an LLM for writing and extended reasoning.</p><p class="caveat">Cost calculated from token usage and published pricing. No LLM speed comparison was run.</p>','Measured median client-observed API request latency: 370.5 ms; p95: 418 ms; two concurrent requests. Cost estimate: 49,260 input tokens × $0.042 / 1,000,000 = $0.00206892, about 0.207 cents for 100 calls. Output tokens free under published pricing; this is a list-price estimate, not a verified invoice. Source: https://docs.typesafe.ai/models . TypeSafe positions JEV for fast structured decisions: https://typesafe.ai/blog/introducing-system-one-models-and-jev . We did not measure a relative speedup, price ratio, or accuracy comparison against an LLM.')
new=[speed]
new.append(slide('Real-time scoring','<p class="intro">Example: update a transcript scorecard as new text arrives.</p><div class="patternflow"><div>Recent transcript<br><small>Text + rubric</small></div><b>→</b><div>JEV<br><small>Score each dimension</small></div><b>→</b><div>Application<br><small>Update the scorecard</small></div></div>'+points([('Clear explanation?','Score whether the speaker explains the idea clearly.'),('Evidence provided?','Score whether claims are supported in the transcript.'),('Question answered?','Check whether the response addresses the question.')])+'<p class="caveat">Your code combines scores and handles uncertain answers.</p>','Illustrative transcript application, not an implemented integration or measured streaming benchmark. TypeSafe documents real-time applications and transcript analysis: https://docs.typesafe.ai/concepts/use-case-map . Composite scoring evaluates independent dimensions and combines scores with application-owned weights: https://docs.typesafe.ai/patterns/composite-scoring . JEV takes text, so live audio must first be transcribed. Debounce transcript updates and evaluate a bounded recent context. Latency depends on input size and workload.'))
new.append(slide('Speculative fan-out for data queries','<p class="intro">Ask about possible query branches together.<br>Use only the answers relevant to the chosen branch.</p><div class="fan"><div class="faninput">“Show revenue in Europe last quarter”</div><div class="fanquestions"><span>Which metric?<br><strong>Revenue</strong></span><span>Which region?<br><strong>Europe</strong></span><span>Which time window?<br><strong>Last quarter</strong></span><span>If orders: which status?<br><strong>Ignored</strong></span></div><div class="fanoutput">One JEV call → code selects an approved query template → database</div></div><p class="caveat">Questions run independently against the same context; code selects the applicable results.</p>','Adapted example, not a measured database integration. Source: https://docs.typesafe.ai/patterns/fan-out . Ask intent and branch-specific questions in one call instead of sequential round trips. Every question must be answerable from the original state; it cannot depend on another question’s answer in the same call. Supply finite metric/region/date-window options, convert dates in code, and use parameterized query templates and normal permissions. Fan-out here speculates on model questions; it does not run every database query or generate arbitrary SQL. TypeSafe says extra questions usually have little latency impact, not zero resource cost.'))
new.append(slide('Decision gating','<p class="intro">A prediction proposes an action.<br>Application rules decide whether to proceed.</p><div class="patternflow"><div>JEV decision<br><small>Label + uncertainty</small></div><b>→</b><div>Policy in code<br><small>Risk + tested threshold</small></div><b>→</b><div>Act or escalate<br><small>Proceed · clarify · review</small></div></div>'+points([('Clear, low-risk match','Apply a support-ticket label automatically.'),('Ambiguous request','Ask a clarifying question or use a stronger model.'),('Consequential action','Require the normal authorization and review checks.')])+'<p class="caveat">Choose thresholds using your own evaluation data; confidence is not a permission check.</p>','Adapted from TypeSafe confidence-gated routing: https://docs.typesafe.ai/patterns/confidence-routing . Confidence describes distribution concentration and should be interpreted in the context of the task: https://docs.typesafe.ai/confidence . No universal threshold guarantees safety or accuracy. Combine label, probabilities, confidence and action-specific policy; retain deterministic authorization.'))
new.append(slide('Smart routing for an agent','<p class="intro">Classify intent and complexity before invoking expensive tools.</p><div class="routes"><div><strong>“Where is my order?”</strong><span>→</span><span>Database lookup</span></div><div><strong>“Compare these products”</strong><span>→</span><span>Specialist LLM</span></div><div><strong>Unclear or complex request</strong><span>→</span><span>Stronger model or human</span></div></div><p class="answer" style="margin-top:32px"><strong>Less setup to add a classifier.<br>Less overhead for everyday decisions.</strong></p><p class="caveat">JEV chooses a bounded route; your application controls execution.</p>','Source: https://docs.typesafe.ai/patterns/intent-routing . TypeSafe describes intent and complexity classification followed by deterministic code, specialist LLMs, or human escalation. These are illustrative routes; validate routing quality and end-to-end latency/cost for the actual workload. The closing thesis: JEV lowers task-specific data/training overhead and offers a fast, low-cost decision option for some work otherwise sent to LLMs.'))
s=s.replace('</main>',''.join(new)+'</main>').replace('01 / 15','01 / 21')
css='''.barart{display:block;width:100%;height:43vh;object-fit:contain;mix-blend-mode:multiply}.barlabels{display:grid;grid-template-columns:1fr 1fr;text-align:center;gap:25px;margin-top:10px}.barlabels strong{display:block;font-size:28px;color:#52704c;margin-bottom:10px}.barlabels span{font-size:19px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:5vw;margin:10px 0 45px}.metrics strong{display:block;font-size:clamp(48px,6vw,90px);letter-spacing:-.06em;color:#52704c;margin-bottom:12px}.metrics span{font-size:24px;line-height:1.4}.patternflow{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:15px 0 44px;font-size:clamp(22px,2.8vw,39px);line-height:1.2}.patternflow>div{border-top:2px solid #52704c;padding-top:18px}.patternflow small{font-size:.56em;color:#526653}.faninput{font-size:30px;padding:20px 0;border-bottom:2px solid #52704c}.fanquestions{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:26px 0;font-size:23px;line-height:1.5}.fanquestions strong{color:#52704c}.fanquestions span:last-child strong{color:#777}.fanoutput{border-top:2px solid #52704c;padding:22px 0;font-size:26px}.routes>div{display:grid;grid-template-columns:1.4fr 40px 1fr;gap:24px;border-top:1px solid #b9c2ad;padding:21px 0;font-size:clamp(20px,2.4vw,33px)}.routes>div>span:last-child{color:#52704c}@media(max-width:700px){.barart{height:33vh}.barlabels strong{font-size:20px}.barlabels span{font-size:15px}.metrics span{font-size:18px}.patternflow{font-size:19px;gap:8px}.faninput{font-size:22px}.fanquestions{grid-template-columns:1fr 1fr;font-size:19px}.fanoutput{font-size:20px}.routes>div{grid-template-columns:1fr 20px 1fr;gap:10px;font-size:18px}}'''
s=s.replace('</style>',css+'</style>');p.write_text(s)
assert s.count('<section')==21
(root/'check-script.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1))
(root/'experiment'/'cost-estimate.json').write_text(json.dumps({'input_tokens':49260,'usd_per_million_input_tokens':.042,'estimated_usd':49260*.042/1e6,'output_tokens_free':True,'source':'https://docs.typesafe.ai/models','invoice_verified':False},indent=2))
print(f'Final presentation: 21 slides, {p.stat().st_size:,} bytes')
